  [8205] = { "近くの敵に雷撃を浴びせ、$D1の間その攻撃間隔を$N1%延ばし、$N3のダメージを与えます。最大$N4体の対象に効果があります。", "攻撃間隔が$N1%長くなっています。", 0x8bc261fe, 0x4f44ee2e, "uu" },
