  [8227] = { "術者の足元に体力 $N1のFlametongue Totemを召喚します。トーテムは$N2ヤード以内にいるすべてのパーティメンバーのメインハンド武器に炎を宿します。攻撃が命中するたびに、武器の速度に応じて$N3のFireダメージを追加で与えます。遅い武器ほど一振りごとのFireダメージが大きくなります。効果時間は$D1です。", nil, 0xd7f74b3f, nil, "um" },
