  [8618] = { "Leatherworkingに使う皮を獣から剥ぎ取る熟練技。skinningスキルを225まで拡張する。Skinning Knifeが必要。", nil, 0xa3e20111, nil, "um" },
  [8621] = { "通常の武器ダメージに加えて$N1のダメージを与える即時攻撃です。コンボポイントを$N2獲得します。", nil, 0x48a8ccda, nil, "um" },
  [8623] = { "コンボポイントごとにダメージを与えるフィニッシュ技です。ダメージはAttack Powerによって増加します：\n $N1ポイント：$N2-$N3ダメージ\n $N4ポイント：$N5-$N6ダメージ\n $N7ポイント：$N8-$N9ダメージ\n $N10ポイント：$N11-$N12ダメージ\n $N13ポイント：$N14-$N15ダメージ", nil, 0xb268c10a, nil, "um" },
  [8624] = { "コンボポイントごとにダメージを与えるフィニッシュ技です。ダメージはAttack Powerによって増加します：\n $N1ポイント：$N2-$N3ダメージ\n $N4ポイント：$N5-$N6ダメージ\n $N7ポイント：$N8-$N9ダメージ\n $N10ポイント：$N11-$N12ダメージ\n $N13ポイント：$N14-$N15ダメージ", nil, 0xb268c10a, nil, "um" },
  [8627] = { "対象をBackstabし、武器ダメージの$N1%に加えて$N2の追加ダメージを与えます。隠密状態で、対象の背後にいる必要があります。コンボポイントを$N3獲得します。", nil, 0x37069d22, nil, "um" },
  [8629] = { "$N1のダメージを与えて攻撃を止め、$D1の間対象を行動不能にします。対象はあなたの方を向いている必要があります。ダメージを受けると効果は解けます。コンボポイントを$N3獲得します。", "行動不能です。", 0x156eba70, 0x147cb83f, "uu" },
  [8631] = { "敵の首を絞め、$D1かけて$N1のダメージを与えます。ダメージはAttack Powerで増加します。ステルス中で、対象の背後にいる必要があります。コンボポイントを$N3獲得します。", "$N2秒ごとに$N1のダメージを受けます。", 0xdd3a1872, 0xef5a123f, "uu" },
  [8632] = { "敵の首を絞め、$D1かけて$N1のダメージを与えます。ダメージはAttack Powerで増加します。ステルス中で、対象の背後にいる必要があります。コンボポイントを$N3獲得します。", "$N2秒ごとに$N1のダメージを受けます。", 0xdd3a1872, 0xef5a123f, "uu" },
  [8633] = { "敵の首を絞め、$D1かけて$N1のダメージを与えます。ダメージはAttack Powerで増加します。ステルス中で、対象の背後にいる必要があります。コンボポイントを$N3獲得します。", "$N2秒ごとに$N1のダメージを受けます。", 0xdd3a1872, 0xef5a123f, "uu" },
  [8637] = { "フェイントを行います。ダメージは与えませんが脅威が大きく下がり、敵に攻撃されにくくなります。", nil, 0x73c372fe, nil, "um" },
  [8639] = { "持続的にダメージを与えるフィニッシュ技です。ダメージはAttack Powerによって増加し、コンボポイントごとに効果時間が長くなります：\n $N1ポイント：$N3秒かけて$N2のダメージ\n $N4ポイント：$N6秒かけて$N5のダメージ\n $N7ポイント：$N9秒かけて$N8のダメージ\n $N10ポイント：$N12秒かけて$N11のダメージ\n $N13ポイント：$N15秒かけて$N14のダメージ", "$N2秒ごとに$N1のダメージを受けます。", 0x8733aeb4, 0x05440273, "uu" },
  [8640] = { "持続的にダメージを与えるフィニッシュ技です。ダメージはAttack Powerによって増加し、コンボポイントごとに効果時間が長くなります：\n $N1ポイント：$N3秒かけて$N2のダメージ\n $N4ポイント：$N6秒かけて$N5のダメージ\n $N7ポイント：$N9秒かけて$N8のダメージ\n $N10ポイント：$N12秒かけて$N11のダメージ\n $N13ポイント：$N15秒かけて$N14のダメージ", "$N2秒ごとに$N1のダメージを受けます。", 0x8733aeb4, 0x05440273, "uu" },
  [8643] = { "対象をスタンさせるフィニッシュ技です。コンボポイントが多いほど長く持続します：\n1ポイント：2秒\n2ポイント：3秒\n3ポイント：4秒\n4ポイント：5秒\n5ポイント：6秒", "スタンしており、ローグから受けるダメージが$N1%増加しています。", 0x6fd561bc, 0x2de153f8, "uu" },
