  [8986] = { "Illusionary Phantasmを$N1体召喚し、$D1の間、術者の戦闘を助けさせます。", nil, 0xef614999, nil, "um" },
  [8988] = { "周囲の敵を沈黙させ、$D1の間呪文を唱えられなくします。", "呪文を詠唱できません。", 0x2d8a29ef, 0x6d133d61, "uu" },
  [8989] = { "$D1持続する鋼の旋風で近くの敵を攻撃し、$D2ごとに武器ダメージに加えて$N2のダメージを与えます。術者は一時的に魔法への耐性を得ます。", "魔法に対する免疫があります。\n通常のダメージに加え、$D1ごとに近くの敵に$N1のダメージを与えています。", 0xd1fe8fef, 0x059c0337, "uu" },
  [8990] = { "近くのパーティメンバーを攻撃したクリーチャーに$N1のHolyダメージを与えます。プレイヤーが同時に受けられるオーラは、パラディン一人につき一つだけです。オーラは解除するまで持続します。", "近接攻撃してきた相手に$N1のHolyダメージを与えます。", 0xb2ca9267, 0x210150aa, "uu" },
  [8992] = { "対象を引き裂き、ダメージの$N1%に99を加えたダメージを与えます。対象の背後にいる必要があります。コンボポイントを$N3獲得します。", nil, 0x6c1a69d4, nil, "um" },
  [8994] = { "敵を追放し、最大$D1の間あらゆる行動を封じますが、無敵状態にします。同時に追放できる対象は1体だけです。", "すべての攻撃と呪文に対する免疫がありますが、行動できません。", 0x0bf23a74, 0xfec93755, "uu" },
  [8995] = { "遠隔武器で対象を撃ちます。", nil, 0x007ce885, nil, "um" },
